  "function contour(w,h,r,ins=0,seg=12){const points=[];const corners=[[w/2-r,h/2-r],[-w/2+r,h/2-r],[-w/2+r,-h/2+r],[w/2-r,-h/2+r]];for(let j=0;j<4;j++)for(let i=0;i<=seg;i++){const a=j*PI/2+i/seg*PI/2,nx=Math.cos(a),ny=Math.sin(a);points.push([corners[j][0]+(r-ins)*nx,corners[j][1]+(r-ins)*ny,nx,ny]);}return points;}",
  "function rounded(w,h,d,r,b=.6,seg=12){",
  " const key=['r',w,h,d,r,b,seg].join();if(geoCache.has(key))return geoCache.get(key);r=Math.min(r,w/2,h/2);b=Math.min(b,d*.49,r*.95);const rings=[],steps=5;",
