  " const label=(text,x,y,size=18,color='#bad1b0',weight=400)=>{ctx.font=`${weight} ${size}px -apple-system, BlinkMacSystemFont, \"Noto Sans CJK SC\", \"PingFang SC\", Arial, sans-serif`;ctx.fillStyle=color;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(text,x,y);};",
