  "  ctx.save();ctx.translate(cx,cy);ctx.rotate(-.5);ctx.strokeStyle='#e6faca45';ctx.lineWidth=1;for(let i=-3;i<=3;i++){ctx.beginPath();ctx.ellipse(0,i*6,r*.9,Math.max(7,r*.55-Math.abs(i)*5),0,PI*.95,TAU*.92);ctx.stroke();}ctx.restore();",
