  "  for(let i=0;i<38;i++){const x=round?72+i*7:51+i*8;const h=(8+Math.abs(Math.sin(i*.65+time*3)*Math.cos(i*.33-time*2))*58)*Math.sin((i+1)/39*PI);cr(x,223-h/2,3.8,h,1.8,ctx);ctx.fillStyle=i%4?'#a7cd83':'#deefc1';ctx.fill();}",
  "  const sec=Math.floor((performance.now()-S.phaseStart)/1000);label('00:'+String(Math.min(sec,59)).padStart(2,'0'),200,305,31,'#e3efd8',500);label('示例音频 · 不启用麦克风',200,346,14,'#819777');pill('结束录音',round?374:399);",
