  "  label({uploading:'连接你的记忆',recalling:'找到相关上下文',planning:'准备好下一步'}[phase],200,round?304:309,23,'#dcebcf',500);label({uploading:'模拟上传中',recalling:'仅检索授权资料 · 示例',planning:'任务生成中 · 示例'}[phase],200,348,16,'#8b9f7e');",
  "  for(let i=0;i<3;i++){ctx.fillStyle=`rgba(177,211,143,${.3+.55*(.5+.5*Math.sin(time*3-i))})`;ctx.beginPath();ctx.arc(185+i*15,round?385:402,3,0,TAU);ctx.fill();}",
  " }else if(phase==='waiting'){",
