  "  label(d.screen[0],200,by+43,19,'#aac88f',500);label(d.screen[1],200,by+91,round?24:27,'#e2eed7',500);label('待你确认 · 模拟任务',200,by+139,14,'#89a178');pill('✓  确认执行',round?364:391);",
  " }else if(phase==='executing'){",
