  "}",
  "const mat=(color,metal=0,rough=.5,extra={})=>({color,metal,rough,...extra});",
  "const palette=Object.fromEntries(Object.values(window.FLO_FINISHES).flat().map(f=>[f.id,f.color]));",
  "const metal=mat([.85,.87,.84],.8,.25),brightMetal=mat([.82,.84,.79],.75,.28),edgeMetal=mat([.45,.49,.46],.9,.2),black=mat([.075,.095,.083],.15,.5),silicone=mat([.49,.525,.47],.06,.85),gold=mat([.78,.64,.37],.8,.35);",
  "const mm=(p=[0,0,0],rot=null)=>rot?M.mul(M.t(...p),rot):M.t(...p);",
  "const models={};",
  "function createModel(shape){",
  " const round=shape==='round',w=round?68:48,h=round?113:88,corner=round?16:10.5,podY=round?35:24.5,screenY=round?-19.5:-15.5;",
  " const objects=[];const add=(geo,material,p=[0,0,0],group='fascia',rot=null)=>{objects.push({geo,material,local:mm(p,rot),group});};",
  " const bodyMat='body',faceMat='face';",
  " // The two-part outer shell and a narrow seam keep the kit visibly buildable.",
  " add(rounded(w,h,12.8,corner,1.8),bodyMat,[0,0,-1.2],'back');",
  " add(rounded(w-.2,h-.2,.65,corner-.1,.24),'seam',[0,0,5.28],'fascia');",
  " add(rounded(w,h,2.8,corner,1.05),faceMat,[0,0,6.8],'fascia');",
  " // C-shaped locating collar, open at TOP for the clip and RIGHT for the button.",
  " add(rounded(26.2,26.2,.85,13.1,.25),mat([.38,.415,.35],.1,.85),[0,podY,8.47]);",
  " add(rounded(24.7,24.7,.45,12.35,.13),mat([.61,.64,.54],.05,.85),[0,podY,8.91]);",
  " add(annulus(14.0,12.15,2.3,18/180*PI,73/180*PI),faceMat,[0,podY,9.05]);",
  " add(annulus(14.0,12.15,2.3,107/180*PI,341/180*PI),faceMat,[0,podY,9.05]);",
  " // The gap at 12 o'clock continues into a small recessed clip channel.",
  " add(rounded(6.4,7.6,.32,1.3,.1),mat([.61,.645,.56],.05,.9),[0,podY+15,8.33]);",
  " // Detachable recording puck, approximately Ø23.2 x 13.45 mm (user image).",
  " add(puck(),metal,[0,0,0],'pod');",
  " add(annulus(11.24,10.9,.2),edgeMetal,[0,0,-4.2],'pod');",
  " // Domed front is part of the lathed recording puck, avoiding a flat painted disc.",
  " // Real clearance target: right-hand physical button, not a left-hand notch.",
  " add(rounded(2.0,5.65,3.65,.96,.38),edgeMetal,[11.42,-.5,-.7],'pod');",
  " add(rounded(1.5,4.7,3,.73,.3),metal,[11.97,-.5,-.7],'pod');",
  " // Independent wearable clip: open loop above the puck, visible from every angle.",
  " add(rounded(5.6,14.5,1.7,1.4,.55),silicone,[0,7.6,-5.9],'pod');",
  " add(frame(6.3,10.8,2.7,1.4,2.0),silicone,[0,14,-5.15],'pod');",
  " // Front microphone grilles remain unobstructed in the docking collar.",
  " for(const yy of[-7.3,7.35]){",
  "  add(rounded(4.7,1.6,.18,.79,.06),mat([.37,.415,.365],.4,.45),[0,yy,6.74],'pod');",
  "  for(let row=0;row<2;row++)for(let col=0;col<6;col++)add(face(.30,.30,.15,6),black,[-1.73+col*.69,yy-.33+row*.66,6.845],'pod');",
  " }",
  " add(rounded(.88,.88,.27,.44,.09,10),'led',[0,4.6,6.84],'pod');",
  " // Bottom touch screen: final rectangular direction, with existing round kit alternative.",
  " if(round){",
  "  add(rounded(61.6,61.6,8.6,30.8,1.1,24),metal,[0,screenY,10.65],'screen');",
  "  add(rounded(57.8,57.8,1.1,28.9,.5,24),black,[0,screenY,14.55],'screen');",
  "  add(annulus(28.05,27.6,.24),edgeMetal,[0,screenY,15.16],'screen');",
  "  add(face(47,47,23.5,30),{...black,texture:screenTextures.round,texMode:2},[0,screenY,15.23],'screen');",
  " }else{",
  "  add(rounded(35.4,42.9,1.6,7.3,.53),mat([.63,.68,.60],.65,.3),[0,screenY,8.84],'screen');",
  "  add(rounded(34.4,41.9,1.4,6.9,.53),black,[0,screenY,9.38],'screen');",
  "  add(face(29.02,35.33,4.6,20),{...black,texture:screenTextures.rect,texMode:2},[0,screenY,10.13],'screen');",
  "  add(frame(34.35,41.85,6.88,.2,.11),edgeMetal,[0,screenY,10.13],'screen');",
  " }",
  " // Subtle wordmark; this is a separate texture, never an external font request.",
  " add(face(10.2,3.4,.01),{color:[1,1,1],texture:textures.logo,texMode:2},[0,-h/2+4.2,8.24]);",
  " // A physical action key and USB-C port, visible when rotated.",
  " add(rounded(4.1,9,1.6,1.7,.52),edgeMetal,[w/2+.05,-13,0.3],'back',M.ry(PI/2));",
  " add(rounded(3.3,7.6,.7,1.4,.25),metal,[w/2+.98,-13,0.3],'back',M.ry(PI/2));",
  " add(rounded(9.1,4.0,.65,1.7,.18),edgeMetal,[0,-h/2-.01,-1.2],'back',M.rx(PI/2));",
  " add(rounded(7.8,2.9,.45,1.35,.13),black,[0,-h/2-.36,-1.2],'back',M.rx(PI/2));",
