  "",
  "function tubePath(points,radius,key){",
  " const out=[],rings=points.map((p,i)=>{const a=points[Math.max(0,i-1)],b=points[Math.min(points.length-1,i+1)];const t=V.norm(V.sub(b,a));const side=V.norm([t[1],-t[0],0]);const up=[t[1]*side[2]-t[2]*side[1],t[2]*side[0]-t[0]*side[2],t[0]*side[1]-t[1]*side[0]];return Array.from({length:10},(_,j)=>{const angle=j/10*TAU;const n=side.map((v,k)=>v*Math.cos(angle)+up[k]*Math.sin(angle));return vertex(p.map((v,k)=>v+radius*n[k]),n,[j/10,i/points.length]);});});",
  " for(let i=0;i<rings.length-1;i++)for(let j=0;j<10;j++){const k=(j+1)%10;quad(out,rings[i][j],rings[i][k],rings[i+1][k],rings[i+1][j]);}return mesh(out,key);",
  "}",
  "function makeAccessories(m,shape){",
  " const strapMat='accessory',silver=mat([.74,.76,.79],.85,.24);",
  " const modes={solo:[],neck:[],wrist:[],phone:[]};",
  " const put=(mode,geo,material,pos=[0,0,0],rot=null)=>modes[mode].push({geo,material,local:mm(pos,rot)});",
  " const neck=Array.from({length:141},(_,i)=>{const a=i/140*TAU;return[38*Math.sin(a),m.h/2+7+88*(1-Math.cos(a))/2,-6-12*Math.sin(a/2)];});",
  " put('neck',tubePath(neck,1.8,'cord-'+shape),strapMat);",
  " put('neck',annulus(6,3.5,3),silver,[0,m.h/2+3,-3]);",
  " put('neck',rounded(12,6,6,2,.6),silver,[0,m.h/2-1,-4]);",
  " // A continuous band wraps around the rear of the enclosure, with physical lugs and buckle.",
  " const out=[],steps=128,ry=m.h/2+16,rz=38;",
  " const point=(a,x,depth)=>{const n=V.norm([0,Math.cos(a)/ry,Math.sin(a)/rz]);return vertex([x,ry*Math.cos(a)+n[1]*depth,-40+rz*Math.sin(a)+n[2]*depth],n);};",
  " for(let i=0;i<steps;i++){const a=i/steps*TAU,b=(i+1)/steps*TAU;for(const d of[-1.5,1.5])quad(out,point(a,-12,d),point(b,-12,d),point(b,12,d),point(a,12,d));for(const x of[-12,12])quad(out,point(a,x,-1.5),point(b,x,-1.5),point(b,x,1.5),point(a,x,1.5));}",
  " put('wrist',mesh(out,'band-'+shape),strapMat);",
  " for(const sign of[-1,1]){put('wrist',rounded(29,10,7,3,1),silver,[0,sign*(m.h/2-1),-6]);put('wrist',rounded(24,21,5,3,1),strapMat,[0,sign*(m.h/2+5),-15],M.rx(sign*.55));}",
  " put('wrist',frame(29,22,4,3,3),silver,[0,-ry+3,-39],M.rx(PI/2));",
  " for(let i=0;i<6;i++)put('wrist',rounded(3,1,4,.4,.2),mat([.05,.05,.05]),[0,ry-4-i*1.8,-45-i*4.4]);",
  " // Phone rear, camera cluster, magnetic mounting ring, and the removable clip cradle.",
  " put('phone',rounded(80,160,8.4,12,1.4),mat([.18,.19,.21],.7,.36),[0,10,-22]);",
  " put('phone',rounded(77.5,157.5,1.2,11,.4),mat([.10,.11,.13],.25,.46),[0,10,-17.5]);",
  " put('phone',annulus(26,24,.6),mat([.45,.46,.48],.6,.3),[0,0,-16.5]);",
  " put('phone',rounded(29,30,3,7,.8),mat([.23,.24,.26],.6,.3),[-20,69,-15]);",
  " for(const [x,y]of[[-26,75],[-14,64],[-26,62]]){put('phone',annulus(5.2,3.9,2),silver,[x,y,-12]);put('phone',face(7.5,7.5,3.75),mat([.025,.035,.055],.6,.1),[x,y,-10.8]);}",
  " put('phone',rounded(m.w+5,m.h*.68,5,6,.7),strapMat,[0,-2,-12]);",
  " for(const sign of[-1,1])put('phone',rounded(4,20,17,1.8,.6),silver,[sign*(m.w/2+1),-2,-7]);",
  " put('phone',rounded(1.8,16,3,.8,.3),silver,[40.5,34,-21]);",
  " return modes;",
  "}",
