  "models.rect=createModel('rect');models.round=createModel('round');",
  "const accessoryModels={rect:makeAccessories(models.rect,'rect'),round:makeAccessories(models.round,'round')};const softBumpers={rect:frame(52,92,12.5,2.2,14),round:frame(72,117,18,2.2,14)};const fabricSleeves={rect:frame(51,91,12,2,13.5),round:frame(71,116,17.5,2,13.5)};const fabricBacks={rect:rounded(49,89,1.8,11,.5),round:rounded(69,114,1.8,16.5,.5)};",
