  " gl.bindBuffer(gl.ARRAY_BUFFER,g.buffer);gl.vertexAttribPointer(A.p,3,gl.FLOAT,false,32,0);gl.vertexAttribPointer(A.n,3,gl.FLOAT,false,32,12);gl.vertexAttribPointer(A.uv,2,gl.FLOAT,false,32,24);",
